#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>
using namespace std;

class Account {
protected:
    string id;
    int balance;
public:
    Account(string i, int b) : id(i), balance(b) {}
    virtual ~Account() {}
    string getId() { return id; }
    int getBalance() { return balance; }
    virtual void take(int amount) {
        if (amount > balance) {
            throw runtime_error("余额不够喵");
        }
        balance = balance - amount;
        cout << id << " 取走 " << amount << " 条，现在 " << balance << " 条" << endl;
    }
};

class CreditAccount : public Account {
protected:
    int limit;
public:
    CreditAccount(string i, int b, int l) : Account(i, b), limit(l) {}
    void take(int amount) override {
        if (amount > balance + limit) {
            throw runtime_error("额度也不够喵");
        }
        balance = balance - amount;
        cout << id << " 取走 " << amount << " 条（能透支），现在 " << balance << " 条" << endl;
    }
};

int main() {
    vector<Account*> roster;
    roster.push_back(new Account("A1", 40));
    roster.push_back(new CreditAccount("C1", 20, 50));

    for (Account* p : roster) {
        try {
            p->take(60);
        } catch (const runtime_error& e) {
            cout << p->getId() << " 这一笔没办成：" << e.what() << endl;
        }
    }

    for (Account* p : roster) {
        cout << p->getId() << " 还剩 " << p->getBalance() << " 条" << endl;
        delete p;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Account {
protected:
    string id;
    int balance;
public:
    Account(string i, int b) : id(i), balance(b) {}
    void save(int amount) {
        balance = balance + amount;
        cout << id << " 存进 " << amount << " 条，现在 " << balance << " 条" << endl;
    }
};

class SavingsAccount : public Account {
protected:
    int rate;
public:
    SavingsAccount(string i, int b, int r) : Account(i, b), rate(r) {}
    int interest() {
        return balance * rate / 100;
    }
    void showInterest() {
        cout << id << " 的利息是 " << interest() << " 条" << endl;
    }
};

int main() {
    SavingsAccount s("S1", 60, 10);
    s.save(40);
    cout << s.interest() << endl;
    s.showInterest();
    return 0;
}
